mapper.select:
SELECT po.product_option_id, po.product_id, po.sku, po.price, po.stock, po.status, p.brand_id, b.brand_name FROM product_option po JOIN product_option_value pov ON po.product_option_id = pov.product_option_id JOIN product p ON po.product_id = p.product_id JOIN brand b ON p.brand_id = b.brand_id WHERE po.product_id = #{product_id} AND pov.option_value_id IN
#{option_value_id}
GROUP BY po.product_option_id, po.product_id, po.sku, po.price, po.stock, po.status, p.brand_id, b.brand_name HAVING COUNT(DISTINCT pov.option_value_id) = #{option_value_count}
